macro.command:
// Draught of the Second Breath
// isDamaged, while the effect lasts: the blow that would drop the drinker to 0 when they drink leaves them at their hit
// point maximum and clears the conditions that hold them down. Later blows that would drop them to 0 call for a
// Constitution save (DC 5 + the damage taken): on a success they drop to 1 instead and the save is counted. Resistance to
// all damage comes from the effect. When the effect ends, a level of exhaustion for each save made.
const FLAG = "secondBreath";
const CLEARED = ["charmed", "frightened", "paralyzed", "poisoned", "stunned"];
const name = macroItem?.name ?? "Draught of the Second Breath";
const say = (content) => ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor }), content: `<strong>${name}</strong>: ${content}` });

if (args[0] === "off") {
  const lastArg = args.at(-1);
  const saves = foundry.utils.getProperty(lastArg?.efData ?? {}, `flags.midi-qol.${FLAG}.saves`) ?? 0;
  if (saves < 1) return say(`the second breath runs out.`);
  const current = actor.system.attributes.exhaustion ?? 0;
  const exhaustion = Math.min(6, current + saves);
  if (exhaustion <= current) return say(`the second breath runs out.`);
  const updates = { "system.attributes.exhaustion": exhaustion };
  if (actor.isOwner) await actor.update(updates);
  else await MidiQOL.socket().executeAsGM("updateActor", { actorUuid: actor.uuid, updates });
  const gained = exhaustion - current;
  await say(`the second breath runs out: ${actor.name} gains ${gained} level${gained > 1 ? "s" : ""} of exhaustion.`);
  return;
}
if (args[0]?.tag !== "TargetOnUse" || args[0].macroPass !== "isDamaged") return;

const di = workflow?.damageItem;
if (!di || di.oldHP < 1 || di.newHP > 0) return;
const effect = actor.effects.find(e => e.getFlag("midi-qol", FLAG) !== undefined);
if (!effect) return;
const state = effect.getFlag("midi-qol", FLAG);

// Damage that leaves exactly 1 hit point, temporary hit points spent first.
const leaveOne = () => {
  const useDetail = MidiQOL.configSettings().useDamageDetail;
  const base = useDetail ? di.totalDamage : di.hpDamage;
  const target = useDetail ? (di.oldTempHP ?? 0) + di.oldHP - 1 : di.oldHP - 1;
  MidiQOL.modifyDamageBy({ damageItem: di, value: target - base, type: "none", reason: name });
  di.newHP = 1;
};

if (!state.risen) {
  // the blow you drink against: rise at the hit point maximum, free of what was holding you down
  leaveOne();
  const max = Math.max(1, actor.system.attributes.hp.max);
  if (max > 1) MidiQOL.modifyDamageBy({ damageItem: di, value: -(max - 1), type: "healing", reason: name });
  di.newHP = max;
  for (const status of CLEARED.filter(s => actor.statuses.has(s)))
    await MidiQOL.socket().executeAsGM("toggleStatusEffect", { actorUuid: actor.uuid, statusId: status, options: { active: false } });
  await MidiQOL.socket().executeAsGM("updateEffects", { actorUuid: actor.uuid, updates: [{ _id: effect.id, [`flags.midi-qol.${FLAG}`]: { risen: true, saves: state.saves ?? 0 } }] });
  return say(`${actor.name} draws a second breath and rises, whole.`);
}

// later blows: hold on with a Constitution save, as undead fortitude
const dc = 5 + Math.max(0, di.totalDamage);
const flavor = `${name} - DC ${dc} Constitution saving throw`;
const save = (await actor.rollSavingThrow({ ability: "con", target: dc }, {}, { flavor, fastForward: true }))?.[0]?.total ?? 0;
if (save < dc) return say(`${actor.name} fails the DC ${dc} Constitution save, and the second breath gives out.`);
leaveOne();
const saves = (state.saves ?? 0) + 1;
await MidiQOL.socket().executeAsGM("updateEffects", { actorUuid: actor.uuid, updates: [{ _id: effect.id, [`flags.midi-qol.${FLAG}.saves`]: saves }] });
await say(`${actor.name} succeeds on a DC ${dc} Constitution save and holds on at 1 hit point (${saves} level${saves > 1 ? "s" : ""} of exhaustion to come).`);
